let wasos_api_key = global.get('wasos_config.api.key');
let wasos_url = global.get('wasos_url');
let wasos_chatroom = global.get('wasos_config.chatroom_name')
let path = "/api/chat/messages/"

if (!wasos_api_key || !wasos_chatroom) {
    node.error('WaSOS not configured');
    return null;
}

msg.url = wasos_url + path + wasos_chatroom;
msg.headers = {
    'x-api-key': wasos_api_key,
    'Content-Type': 'application/json'
};

return msg;
